import React, { useState } from "react";
import styled from "styled-components";

import { useDialogShortcuts } from "../../hooks/useDialogShortcuts";

import { AddIcon } from "@mendix/ide-icons/AddIcon";
import { ToolbarButton } from "@mendix/ide-ui-components/toolbar/ToolbarButton";

import { DeleteIcon } from "@mendix/ide-icons/DeleteIcon";
import { IconButton } from "@mendix/ide-ui-components/button/IconButton";
import { Headers } from "../../types/consumedMCPService";
import { InfoBanner } from "../components/Banner";
import DialogFooter from "../components/DialogFooter";
import { StyledInput } from "../components/elements/formelements";
import GroupBox from "../components/GroupBox";
import { ContentColumn, PageContainerDialog, PageContent } from "../components/PageContainers";
import Table from "../components/Table";

interface AuthenticationHeadersEditorProps {
    headers: Headers;
    onClose: (headers: Headers | null) => void;
}

const BoldText = styled.span`
    font-weight: bold;
`;

const AuthenticationHeadersEditor: React.FC<AuthenticationHeadersEditorProps> = (props) => {
    const [headers, setHeaders] = useState(props.headers);

    const addHeader = () => {
        setHeaders((prev) => [...prev, ["", ""]]);
    };

    const updateKey = (index: number, newKey: string) => {
        setHeaders((prev) => prev.map((entry, i) => (i === index ? [newKey, entry[1]] : entry)));
    };

    const updateValue = (index: number, newValue: string) => {
        setHeaders((prev) => prev.map((entry, i) => (i === index ? [entry[0], newValue] : entry)));
    };

    const deleteHeader = (index: number) => {
        setHeaders((prev) => prev.filter((_, i) => i !== index));
    };

    const handleOk = () => {
        props.onClose(headers);
    };

    const handleCancel = () => {
        props.onClose(null);
    };

    useDialogShortcuts(handleCancel, handleOk);

    return (
        <PageContainerDialog>
            <PageContent>
                <ContentColumn>
                    <GroupBox label="Authentication Headers">
                        <InfoBanner>
                            <BoldText>The headers below are not stored.</BoldText>
                            <div>
                                The headers are only used to explore tools from Studio Pro. To authenticate with MCP
                                servers at runtime, please provide a credentials microflow.
                            </div>
                        </InfoBanner>
                        <Table
                            ariaLabel="Authentication headers table"
                            columns={[
                                { id: "key", caption: "Key", isRowHeader: true, resizable: true },
                                { id: "value", caption: "Value", resizable: true },
                                { id: "delete", caption: "", minWidth: 32, defaultWidth: 32, maxWidth: 32 },
                            ]}
                            data={headers.map((entry, index) => [
                                <StyledInput
                                    key={`key-${index}`}
                                    aria-label={`Header key ${index + 1}`}
                                    value={entry[0]}
                                    onChange={(v: string) => updateKey(index, v)}
                                    placeholder="Key"
                                />,
                                <StyledInput
                                    key={`value-${index}`}
                                    aria-label={`Header value ${index + 1}`}
                                    value={entry[1]}
                                    onChange={(v: string) => updateValue(index, v)}
                                    placeholder="Value"
                                />,
                                <IconButton icon={<DeleteIcon />} onPress={() => deleteHeader(index)} />,
                            ])}
                            toolbarLeft={
                                <ToolbarButton
                                    icon={<AddIcon />}
                                    label="Add header"
                                    aria-label="Add header"
                                    tooltip="Add a new header"
                                    onPress={addHeader}
                                />
                            }
                        />
                    </GroupBox>
                </ContentColumn>
            </PageContent>
            <DialogFooter onOk={handleOk} showHelp={false} onCancel={handleCancel} />
        </PageContainerDialog>
    );
};

export default AuthenticationHeadersEditor;
